import React, {useContext, useMemo, useState, useEffect} from 'react';
import {KeyboardAvoidingView, Platform, View} from 'react-native';
import {BlurView} from '@react-native-community/blur';
import {Icon, SearchBar as RNESearchBar, Text} from 'react-native-elements';
import {useBottomTabBarHeight} from '@react-navigation/bottom-tabs';
import ThemeContext from '../../contexts/ThemeContext';
import {Theme} from '../../types/interfaces';
import styles from '../../styles/CardSearchFooterStyles';

interface RulesSearchFooterProps {
  query: string;
  onQueryChange: (value: string) => void;
  onClearQuery: () => void;
  showToc: boolean;
  onToggleToc: () => void;
  filteredCount: number;
  totalCount: number;
  hitCount: number;
}

const fallbackTheme: Theme = {
  name: 'dark',
  backgroundColor: '#000000',
  foregroundColor: '#FFFFFF',
  dividerColor: '#444444',
  translucentBackgroundColor: 'rgba(0,0,0,0.5)',
};

const RulesSearchFooter = ({
  query,
  onQueryChange,
  onClearQuery,
  showToc,
  onToggleToc,
  filteredCount,
  totalCount,
  hitCount,
}: RulesSearchFooterProps) => {
  const theme = useContext<Theme | null>(ThemeContext) || fallbackTheme;
  const tabBarHeight = useBottomTabBarHeight();
  const [localQuery, setLocalQuery] = useState(query);

  useEffect(() => {
    if (query === '' && localQuery !== '') {
      setLocalQuery('');
    }
  }, [query, localQuery]);

  const statusText = useMemo(() => {
    if (!query.trim()) {
      return `Showing ${totalCount} sections`;
    }
    return `Showing ${filteredCount} of ${totalCount} sections • ${hitCount} hit${
      hitCount === 1 ? '' : 's'
    }`;
  }, [query, filteredCount, totalCount, hitCount]);

  const bottomGlassPadding = Math.max(tabBarHeight, 58) + 2;

  return (
    <KeyboardAvoidingView
      behavior={Platform.OS === 'ios' ? 'position' : undefined}
      keyboardVerticalOffset={0}
      style={styles.overlayWrapper}
      pointerEvents="box-none">
      <View
        pointerEvents="box-none"
        style={{
          ...styles.glassDockContainer,
          bottom: 0,
          borderTopColor: theme.dividerColor,
        }}>
        <BlurView
          style={styles.glassDockBlur}
          blurType={theme.name === 'dark' ? 'dark' : 'light'}
          blurAmount={18}
          reducedTransparencyFallbackColor={theme.translucentBackgroundColor}
        />
        <View
          pointerEvents="box-none"
          style={{
            ...styles.glassDockContent,
            paddingBottom: bottomGlassPadding,
          }}>
          <View style={styles.statusRowSlot}>
            <Text style={{color: theme.foregroundColor, fontSize: 13, fontWeight: '600'}}>
              {statusText}
            </Text>
          </View>
          <RNESearchBar
            platform="default"
            testID="rules-search-input"
            placeholder="Search rules"
            value={localQuery}
            onChangeText={text => {
              setLocalQuery(text);
              onQueryChange(text);
            }}
            onClear={() => {
              setLocalQuery('');
              onClearQuery();
            }}
            autoCorrect={false}
            autoCapitalize="none"
            round={true}
            containerStyle={{
              ...styles.searchBarContainer,
              ...styles.searchBarTight,
            }}
            inputContainerStyle={{
              backgroundColor: theme.translucentBackgroundColor,
            }}
            searchIcon={{
              name: showToc ? 'book' : 'book-outline',
              type: 'ionicon',
              color: theme.foregroundColor,
              testID: 'rules-toc-toggle',
              accessibilityLabel: 'rules-toc-toggle',
              onPress: onToggleToc,
            }}
            clearIcon={{
              name: 'close-outline',
              type: 'ionicon',
              color: theme.foregroundColor,
            }}
          />
        </View>
      </View>
    </KeyboardAvoidingView>
  );
};

export default RulesSearchFooter;
